import unittest
from candidate import filter_by_prefix

class TestFilterByPrefix(unittest.TestCase):
    def test_filter_by_prefix_empty_list(self):
        self.assertEqual(filter_by_prefix([], 'a'), [])

    def test_filter_by_prefix_single_match(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde'], 'a'), ['abc'])

    def test_filter_by_prefix_multiple_matches(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde', 'array'], 'a'), ['abc', 'array'])

    def test_filter_by_prefix_no_matches(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde'], 'f'), [])

    def test_filter_by_prefix_prefix_is_empty_string(self):
        self.assertEqual(filter_by_prefix(['abc', 'bcd', 'cde'], ''), ['abc', 'bcd', 'cde'])

    def test_filter_by_prefix_input_list_is_none(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(None, 'a')

    def test_filter_by_prefix_prefix_is_none(self):
        with self.assertRaises(TypeError):
            filter_by_prefix(['abc', 'bcd', 'cde'], None)

    def test_filter_by_prefix_input_list_contains_non_string(self):
        with self.assertRaises(AttributeError):
            filter_by_prefix(['abc', 123, 'cde'], 'a')

if __name__ == '__main__':
    unittest.main()
